<script setup>
import{ref,onMounted}from'vue';import{useRoute}from'vue-router';import{ElMessage}from'element-plus';import api from'../services/api.js';import GuideCard from'../components/GuideCard.vue';import SectionTitle from'../components/SectionTitle.vue';import{Calendar,Wallet,Sunny,Location}from'@element-plus/icons-vue'
const route=useRoute(),data=ref(null),loading=ref(true),error=ref('');onMounted(async()=>{try{data.value=await api.get(`/public/destinations/${route.params.id}`)}catch(e){error.value=e.message;ElMessage.error(e.message)}finally{loading.value=false}})
</script>
<template><div v-if="loading" class="loading-panel"><el-skeleton :rows="10" animated/></div><div v-else-if="data" class="destination-detail"><section class="detail-hero" :style="{backgroundImage:`linear-gradient(90deg,rgba(7,35,42,.78),rgba(7,35,42,.08)),url(${data.coverImage})`}"><div class="container"><span>{{data.nameEn}} · {{data.type}}</span><h1>{{data.name}}</h1><p>{{data.summary}}</p><div class="quick-facts"><div><el-icon><Sunny/></el-icon><span>推荐季节<b>{{data.season}}</b></span></div><div><el-icon><Calendar/></el-icon><span>建议游玩<b>{{data.suggestedDays}} 天</b></span></div><div><el-icon><Wallet/></el-icon><span>平均预算<b>¥{{Number(data.averageBudget).toLocaleString()}}</b></span></div><div><el-icon><Location/></el-icon><span>位置<b>{{data.locationText}}</b></span></div></div></div></section><section class="section"><div class="container story-layout"><article><span class="eyebrow">ABOUT THE PLACE</span><h2>在 {{data.name}}，慢慢找到自己的节奏</h2><p>{{data.description}}</p><div class="tags"><span v-for="tag in data.tags?.split(',')" :key="tag"># {{tag}}</span></div></article><aside><b>旅行提示</b><p>开放时间、天气与费用会随季节变化，出发前请以当地最新公告为准。</p><p>坐标参考：{{data.latitude}}, {{data.longitude}}</p></aside></div></section><section class="section soft"><div class="container"><SectionTitle eyebrow="PLACES TO VISIT" title="值得停留的地方" subtitle="不必全部打卡，选几个真正感兴趣的就好"/><div class="spot-grid"><div v-for="spot in data.scenicSpots" :key="spot.id" class="spot"><img :src="spot.coverImage||spot.cover_image" :alt="spot.name"><div><h3>{{spot.name}}</h3><p>{{spot.summary}}</p><span>建议 {{spot.suggestedHours??spot.suggested_hours}} 小时 · {{spot.recommendedSeason||spot.recommended_season}}</span></div></div></div></div></section><section class="section"><div class="container"><SectionTitle eyebrow="TRAVEL NOTES" :title="`关于 ${data.name} 的精选攻略`" subtitle="来自真实创作者的路线、预算与在地经验"/><div class="guide-grid"><GuideCard v-for="guide in data.guides" :key="guide.id" :guide="guide"/></div></div></section><section class="gallery-section"><div class="container"><SectionTitle eyebrow="GALLERY" title="沿途画面"/><div class="gallery"><img v-for="(item,index) in data.gallery" :key="index" :src="item.image_url||item.imageUrl" :alt="item.caption"></div></div></section></div><div v-else class="empty-panel">{{error||'目的地不存在或已下架'}}</div></template>
<style scoped>.detail-hero{height:580px;background-size:cover;background-position:center;color:white;display:flex;align-items:end;padding-bottom:54px}.detail-hero>div>span{letter-spacing:3px;font-size:11px;color:#bce8ea}.detail-hero h1{font-family:Georgia,"Songti SC",serif;font-size:68px;margin:10px 0}.detail-hero>div>p{max-width:650px;font-size:16px;line-height:1.8}.quick-facts{margin-top:38px;display:flex;gap:35px}.quick-facts>div{display:flex;align-items:center;gap:10px}.quick-facts .el-icon{font-size:25px;color:#f2c46d}.quick-facts span{font-size:11px;color:rgba(255,255,255,.7)}.quick-facts b{display:block;color:white;font-size:14px;margin-top:5px}.story-layout{display:grid;grid-template-columns:2fr 1fr;gap:90px}.story-layout h2{font-family:Georgia,"Songti SC",serif;font-size:36px;line-height:1.5}.story-layout article>p{font-size:16px;line-height:2;color:#587279}.story-layout aside{background:#e8f4f2;padding:28px;border-radius:16px;align-self:start}.story-layout aside p{color:#607b80;line-height:1.8;font-size:13px}.tags span{display:inline-block;border:1px solid #cddfdd;border-radius:16px;padding:6px 12px;margin:6px 5px 0 0;font-size:12px;color:#167c8c}.spot-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.spot{display:grid;grid-template-columns:180px 1fr;background:white;border-radius:15px;overflow:hidden}.spot img{width:100%;height:160px;object-fit:cover}.spot>div{padding:18px}.spot h3{margin:0;font-family:Georgia,"Songti SC",serif}.spot p{color:#6a8185;font-size:12px;line-height:1.65}.spot span{font-size:11px;color:#167c8c}.gallery-section{padding:70px 0;background:#123b43;color:white}.gallery-section :deep(.section-heading){color:white}.gallery{columns:3;column-gap:14px}.gallery img{width:100%;border-radius:12px;margin-bottom:14px;break-inside:avoid}.gallery img:nth-child(3n+1){aspect-ratio:4/3;object-fit:cover}.gallery img:nth-child(3n+2){aspect-ratio:1/1;object-fit:cover}@media(max-width:760px){.detail-hero{height:520px}.detail-hero h1{font-size:48px}.quick-facts{display:grid;grid-template-columns:1fr 1fr;gap:18px}.story-layout{grid-template-columns:1fr;gap:25px}.spot-grid{grid-template-columns:1fr}.spot{grid-template-columns:130px 1fr}.gallery{columns:2}}</style>
